window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-57739dc71bba505b"]={"versions": [{"id": "FIG-57739dc71bba505b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template (M1-Metamodell). Es definiert die strukturelle Anbindung von Software-Datendefinitionseigenschaften an Systemkonstanten zur Unterstützung der Compile- und Post-Build-Variabilität in AUTOSAR-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen und deren Komposition:</p>\n<ul class=\"fig-list\"><li><code>SwSystemconst</code>: Trägt die Stereotypen <code>«ARElement»</code> und <code>«AtpDefinition»</code>. Dient als Top-Level-Element zur Modellierung einer Systemkonstante.\n</li><li><code>SwDataDefProps</code>: Trägt den Stereotyp <code>«atpVariation»</code>. Enthält Datendefinitionseigenschaften:\n<ul class=\"fig-list\"><li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code>\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>stepSize: Float [0..1]</code>\n</li><li><code>swAlignment: AlignmentType [0..1]</code>\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code>\n</li><li><code>swIntendedResolution: Numerical [0..1]</code>\n</li><li><code>swInterpolationMethod: Identifier [0..1]</code>\n</li><li><code>swIsVirtual: Boolean [0..1]</code>\n</li><li>Unterabschnitt <code>«atpVariation»</code>:\n<ul class=\"fig-list\"><li><code>swValueBlockSize: Numerical [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li>Assoziation: Komposition (gefüllte Raute) von <code>SwSystemconst</code> zu <code>SwDataDefProps</code> mit Rollenname <code>+swDataDefProps</code> und Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Beschreibt deklarative M1-Konfigurationsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für die M1-Konfiguration. Ein <code>SwSystemconst</code> ist als <code>ARElement</code> paketierbar und referenzierbar (<code>AtpDefinition</code>). Die Bindung an <code>SwDataDefProps</code> mit Multiplizität 0..1 erlaubt optional detaillierte softwaretechnische Typisierungs-, Kalibrier- und Adressierungseigenschaften. Das Stereotyp <code>«atpVariation»</code> an <code>SwDataDefProps</code> sowie am Attribut <code>swValueBlockSize</code> ermöglicht die Definition von Varianten im Modell über Variation Points. Alle Attribute von <code>SwDataDefProps</code> sind optional (Kardinalität <code>0..1</code>).</p>"}, {"id": "FIG-fd9a39c241dd4814", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template (M1-Metamodell). Es definiert die strukturelle Anbindung von Software-Datendefinitionseigenschaften an Systemkonstanten zur Unterstützung der Compile- und Post-Build-Variabilität in AUTOSAR-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen und deren Komposition:</p>\n<ul class=\"fig-list\"><li><code>SwSystemconst</code>: Trägt die Stereotypen <code>«ARElement»</code> und <code>«AtpDefinition»</code>. Dient als Top-Level-Element zur Modellierung einer Systemkonstante.\n</li><li><code>SwDataDefProps</code>: Trägt den Stereotyp <code>«atpVariation»</code>. Enthält Datendefinitionseigenschaften:\n<ul class=\"fig-list\"><li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code>\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>displayPresentation: DisplayPresentationEnum [0..1]</code>\n</li><li><code>stepSize: Float [0..1]</code>\n</li><li><code>swAlignment: AlignmentType [0..1]</code>\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code>\n</li><li><code>swIntendedResolution: Numerical [0..1]</code>\n</li><li><code>swInterpolationMethod: Identifier [0..1]</code>\n</li><li><code>swIsVirtual: Boolean [0..1]</code>\n</li><li>Unterabschnitt <code>«atpVariation»</code>:\n<ul class=\"fig-list\"><li><code>swValueBlockSize: Numerical [0..1]</code>\n</li><li><code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li>Assoziation: Komposition (gefüllte Raute) von <code>SwSystemconst</code> zu <code>SwDataDefProps</code> mit Rollenname <code>+swDataDefProps</code> und Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Beschreibt deklarative M1-Konfigurationsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für die M1-Konfiguration. Ein <code>SwSystemconst</code> ist als <code>ARElement</code> paketierbar und referenzierbar (<code>AtpDefinition</code>). Die Bindung an <code>SwDataDefProps</code> mit Multiplizität 0..1 erlaubt optional detaillierte softwaretechnische Typisierungs-, Kalibrier- und Adressierungseigenschaften inklusive <code>displayPresentation</code> und mehrdimensionaler Blockgrößen (<code>swValueBlockSizeMult</code>). Das Stereotyp <code>«atpVariation»</code> an <code>SwDataDefProps</code> sowie an den Attributen <code>swValueBlockSize</code> und <code>swValueBlockSizeMult</code> ermöglicht die variantenabhängige Ausprägung dieser Eigenschaften. Alle skalaren Attribute sind optional (<code>0..1</code>), das Attribut <code>swValueBlockSizeMult</code> ist eine geordnete Liste (<code>[0..*] {ordered}</code>).</p>"}, {"id": "FIG-ae2ce020dde2015d", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template (M1-Metamodell). Es definiert die strukturelle Anbindung von Software-Datendefinitionseigenschaften an Systemkonstanten zur Unterstützung der Compile- und Post-Build-Variabilität in AUTOSAR-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen und deren Komposition:</p>\n<ul class=\"fig-list\"><li><code>SwSystemconst</code>: Trägt die Stereotypen <code>«ARElement»</code> und <code>«AtpDefinition»</code>. Dient als Top-Level-Element zur Modellierung einer Systemkonstante.\n</li><li><code>SwDataDefProps</code>: Trägt den Stereotyp <code>«atpVariation»</code>. Enthält Datendefinitionseigenschaften:\n<ul class=\"fig-list\"><li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code>\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>displayPresentation: DisplayPresentationEnum [0..1]</code>\n</li><li><code>stepSize: Float [0..1]</code>\n</li><li><code>swAlignment: AlignmentType [0..1]</code>\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code>\n</li><li><code>swIntendedResolution: Numerical [0..1]</code>\n</li><li><code>swInterpolationMethod: Identifier [0..1]</code>\n</li><li><code>swIsVirtual: Boolean [0..1]</code>\n</li><li>Unterabschnitt <code>«atpVariation»</code>:\n<ul class=\"fig-list\"><li><code>swValueBlockSize: Numerical [0..1]</code>\n</li><li><code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li>Assoziation: Komposition (gefüllte Raute) von <code>SwSystemconst</code> zu <code>SwDataDefProps</code> mit Rollenname <code>+swDataDefProps</code> und Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Beschreibt deklarative M1-Konfigurationsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für die M1-Konfiguration. Ein <code>SwSystemconst</code> ist als <code>ARElement</code> paketierbar und referenzierbar (<code>AtpDefinition</code>). Die Bindung an <code>SwDataDefProps</code> mit Multiplizität 0..1 erlaubt optional detaillierte softwaretechnische Typisierungs-, Kalibrier- und Adressierungseigenschaften inklusive <code>displayPresentation</code> und mehrdimensionaler Blockgrößen (<code>swValueBlockSizeMult</code>). Das Stereotyp <code>«atpVariation»</code> an <code>SwDataDefProps</code> sowie an den Attributen <code>swValueBlockSize</code> und <code>swValueBlockSizeMult</code> ermöglicht die variantenabhängige Ausprägung dieser Eigenschaften. Alle skalaren Attribute sind optional (<code>0..1</code>), das Attribut <code>swValueBlockSizeMult</code> ist eine geordnete Liste (<code>[0..*] {ordered}</code>).</p>"}, {"id": "FIG-fb965b223240cc3e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Software-Systemkonstanten im AUTOSAR Generic Structure Template (M1-Metamodell). Es definiert die strukturelle Anbindung von Software-Datendefinitionseigenschaften an Systemkonstanten zur Unterstützung der Compile- und Post-Build-Variabilität in AUTOSAR-Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen und deren Komposition:</p>\n<ul class=\"fig-list\"><li><code>SwSystemconst</code>: Trägt die Stereotypen <code>«ARElement»</code> und <code>«AtpDefinition»</code>. Dient als Top-Level-Element zur Modellierung einer Systemkonstante.\n</li><li><code>SwDataDefProps</code>: Trägt den Stereotyp <code>«atpVariation»</code>. Enthält Datendefinitionseigenschaften:\n<ul class=\"fig-list\"><li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code>\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>displayPresentation: DisplayPresentationEnum [0..1]</code>\n</li><li><code>stepSize: Float [0..1]</code>\n</li><li><code>swAlignment: AlignmentType [0..1]</code>\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li><li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code>\n</li><li><code>swIntendedResolution: Numerical [0..1]</code>\n</li><li><code>swInterpolationMethod: Identifier [0..1]</code>\n</li><li><code>swIsVirtual: Boolean [0..1]</code>\n</li><li>Unterabschnitt <code>«atpVariation»</code>:\n<ul class=\"fig-list\"><li><code>swValueBlockSize: Numerical [0..1]</code>\n</li><li><code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code>\n</li></ul>\n</li></ul>\n</li><li>Assoziation: Komposition (gefüllte Raute) von <code>SwSystemconst</code> zu <code>SwDataDefProps</code> mit Stereotyp <code>«atpSplitable»</code>, Rollenname <code>+swDataDefProps</code> und Kardinalität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitverhalten. Beschreibt deklarative M1-Konfigurationsstrukturen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für die M1-Konfiguration. Ein <code>SwSystemconst</code> ist als <code>ARElement</code> paketierbar und referenzierbar (<code>AtpDefinition</code>). Die Bindung an <code>SwDataDefProps</code> ist als <code>«atpSplitable»</code> gekennzeichnet, sodass die Eigenschaften über separate ARXML-Dateifragmente oder Teillieferungen hinweg aufgeteilt und zusammengeführt werden können. Das Stereotyp <code>«atpVariation»</code> an <code>SwDataDefProps</code> sowie an den Attributen <code>swValueBlockSize</code> und <code>swValueBlockSizeMult</code> gestattet die variantenabhängige Ausprägung im Modell. Alle skalaren Attribute sind optional (<code>0..1</code>), das Attribut <code>swValueBlockSizeMult</code> ist eine geordnete Liste (<code>[0..*] {ordered}</code>).</p>"}], "trans": [{"from": "FIG-57739dc71bba505b", "to": "FIG-fd9a39c241dd4814", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>SwDataDefProps</code> wurden die Attribute <code>displayPresentation: DisplayPresentationEnum [0..1]</code> und <code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-fd9a39c241dd4814", "to": "FIG-ae2ce020dde2015d", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ae2ce020dde2015d", "to": "FIG-fb965b223240cc3e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Kompositionsbeziehung <code>swDataDefProps</code> von <code>SwSystemconst</code> zu <code>SwDataDefProps</code> wurde mit dem Stereotyp <code>«atpSplitable»</code> versehen.\n</li></ul>"}]};
